#!/usr/bin/env node

/**
 * CASE PAGES, FROM ONE FILE PER VIDEO.
 *
 * Each published case video is one JSON file in content/cases/. This script
 * turns them into:
 *
 *   cases/index.html          the gallery, newest first, with topic filters
 *   cases/<slug>/index.html   one page per video: the video, the rounded
 *                             situation, the question, and an Apply button
 *   index.html                the "Latest cases" block between its markers
 *   sitemap.xml               every public page
 *
 * Generated files are committed. `--check` fails when any of them is stale,
 * the same way generate:module-manifest does, so a case added without running
 * the generator cannot reach the site half-published.
 *
 * A case with no youtubeId is a draft (the admin's "Copy public case JSON"
 * produces one) and is skipped with a note, not published.
 */

import { readFile, readdir, writeFile, mkdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { TOPICS } from '../js/case_application/schema.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONTENT_DIR = path.join(ROOT, 'content', 'cases');
const CASES_DIR = path.join(ROOT, 'cases');
const HOME_FILE = path.join(ROOT, 'index.html');
const SITEMAP_FILE = path.join(ROOT, 'sitemap.xml');
const SITE = 'https://planeir.ie';
const MARKER = '<!-- Generated by scripts/generate-case-pages.mjs. Edit content/cases/*.json and run npm run generate:cases. -->';
const LATEST_START = '<!-- cases:latest:start -->';
const LATEST_END = '<!-- cases:latest:end -->';
const LATEST_COUNT = 3;
const STATIC_PAGES = ['/', '/apply/', '/cases/', '/for-ai-assistants/', '/privacy/'];

const TOPIC_LABELS = new Map(TOPICS.map((topic) => [topic.id, topic.label]));
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const checkOnly = process.argv.includes('--check');

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function jsonForScript(value) {
  return JSON.stringify(value, null, 2).replace(/</g, '\\u003c');
}

function formatDate(iso) {
  const [year, month, day] = iso.split('-').map(Number);
  return `${day} ${MONTHS[month - 1]} ${year}`;
}

function durationLabel(duration) {
  const match = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(duration || '');
  if (!match) return '';
  const [hours, minutes, seconds] = match.slice(1).map((part) => Number(part || 0));
  const totalMinutes = hours * 60 + minutes;
  return `${totalMinutes}:${String(seconds).padStart(2, '0')}`;
}

/* ---------- reading and checking the content ---------- */

function problemsWith(entry, file) {
  const problems = [];
  const slug = path.basename(file, '.json');
  const need = (condition, message) => {
    if (!condition) problems.push(`${file}: ${message}`);
  };
  need(entry && typeof entry === 'object' && !Array.isArray(entry), 'must be a JSON object');
  if (problems.length > 0) return problems;

  need(entry.slug === slug, `slug must be "${slug}" to match the file name`);
  need(/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.slug || '') && entry.slug.length <= 80, 'slug must be lowercase words joined by hyphens');
  need(typeof entry.title === 'string' && entry.title.trim() && entry.title.length <= 140, 'title is required (140 characters at most)');
  need(/^\d{4}-\d{2}-\d{2}$/.test(entry.publishedDate || '') && !Number.isNaN(Date.parse(entry.publishedDate)), 'publishedDate must be YYYY-MM-DD');
  need(/^[A-Za-z0-9_-]{11}$/.test(entry.youtubeId || ''), 'youtubeId must be the 11-character YouTube id');
  need(!entry.duration || durationLabel(entry.duration), 'duration must look like PT9M40S');
  need(Array.isArray(entry.topics) && entry.topics.every((topic) => TOPIC_LABELS.has(topic)), `topics must be from: ${[...TOPIC_LABELS.keys()].join(', ')}`);
  need(typeof entry.summary === 'string' && entry.summary.trim() && entry.summary.length <= 300, 'summary is required (300 characters at most)');
  need(typeof entry.question === 'string' && entry.question.trim() && entry.question.length <= 600, 'question is required (600 characters at most)');
  need(Array.isArray(entry.covers) && entry.covers.length <= 8 && entry.covers.every((item) => typeof item === 'string' && item.trim()), 'covers must be a list of up to 8 lines');
  need(Array.isArray(entry.situation) && entry.situation.length > 0, 'situation is required');
  if (Array.isArray(entry.situation)) {
    entry.situation.forEach((section, index) => {
      need(section && typeof section.heading === 'string' && section.heading.trim(), `situation[${index}].heading is required`);
      need(Array.isArray(section?.lines) && section.lines.length > 0, `situation[${index}].lines is required`);
      (section?.lines || []).forEach((line, lineIndex) => {
        const ok = typeof line === 'string'
          ? Boolean(line.trim())
          : Boolean(line && typeof line.label === 'string' && Array.isArray(line.lines) && line.lines.every((item) => typeof item === 'string'));
        need(ok, `situation[${index}].lines[${lineIndex}] must be text, or { label, lines }`);
      });
    });
  }
  return problems;
}

async function loadCases() {
  let files = [];
  try {
    files = (await readdir(CONTENT_DIR)).filter((name) => name.endsWith('.json')).sort();
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }

  const published = [];
  const drafts = [];
  const problems = [];
  for (const name of files) {
    const file = `content/cases/${name}`;
    let entry;
    try {
      entry = JSON.parse(await readFile(path.join(CONTENT_DIR, name), 'utf8'));
    } catch (error) {
      problems.push(`${file}: is not valid JSON (${error.message})`);
      continue;
    }
    if (!entry?.youtubeId) {
      drafts.push(file);
      continue;
    }
    const found = problemsWith(entry, file);
    if (found.length > 0) problems.push(...found);
    else published.push(entry);
  }

  published.sort((a, b) => b.publishedDate.localeCompare(a.publishedDate) || a.slug.localeCompare(b.slug));
  return { published, drafts, problems };
}

/* ---------- rendering ---------- */

function head({ title, description, canonical, depth, extra = '' }) {
  const up = '../'.repeat(depth);
  return `<!doctype html>
<html lang="en-IE">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="color-scheme" content="dark" />
    <meta name="description" content="${escapeHtml(description)}" />
    <meta name="robots" content="index, follow" />
    <link rel="canonical" href="${canonical}" />
    <meta property="og:site_name" content="Planeir" />
    <meta property="og:url" content="${canonical}" />
    <meta property="og:title" content="${escapeHtml(title)}" />
    <meta property="og:description" content="${escapeHtml(description)}" />
    <meta property="og:locale" content="en_IE" />
    <title>${escapeHtml(title)}</title>
    <link rel="icon" type="image/svg+xml" href="${up}favicon.svg" />
    <link rel="icon" type="image/png" sizes="32x32" href="${up}favicon-32.png" />
    <link rel="shortcut icon" href="${up}favicon.ico" />
    <link rel="apple-touch-icon" sizes="180x180" href="${up}apple-touch-icon.png" />
    <link rel="stylesheet" href="${up}styles/landing.css" />
    <link rel="stylesheet" href="${up}styles/cases.css" />${extra}
  </head>`;
}

function header(depth) {
  const up = '../'.repeat(depth);
  return `      <header class="site-header">
        <a class="site-brand" href="${up}" aria-label="Planeir home">
          <span class="site-brand-logo-wrap" aria-hidden="true">
            <img
              class="site-brand-logo"
              src="${up}assets/brand/planeir-lockup-light.svg"
              alt="Planeir logo"
              width="1330"
              height="384"
              decoding="async"
            />
          </span>
        </a>
        <nav class="site-header-actions" aria-label="Site">
          <a class="site-nav-admin-login" href="${up}cases/">All cases</a>
          <a class="button button-primary button-sm" href="${up}apply/">Apply</a>
        </nav>
      </header>`;
}

function footer(depth) {
  const up = '../'.repeat(depth);
  return `      <footer class="site-footer">
        <p class="site-footer-note">
          Planeir is educational only, not regulated financial advice.
          <a href="${up}privacy/">Privacy</a> ·
          <a href="mailto:hello@planeir.ie">hello@planeir.ie</a>
        </p>
      </footer>`;
}

function page({ headHtml, depth, body, scripts = '' }) {
  return `${headHtml}
  <body>
    ${MARKER}
    <div class="landing-shell">
      <div class="landing-ambient landing-ambient-one" aria-hidden="true"></div>
      <div class="landing-ambient landing-ambient-two" aria-hidden="true"></div>
      <div class="landing-grid" aria-hidden="true"></div>

${header(depth)}

${body}

${footer(depth)}
    </div>${scripts}
  </body>
</html>
`;
}

function topicTags(topics) {
  if (topics.length === 0) return '';
  return `<ul class="case-tags">${topics.map((topic) => `<li>${escapeHtml(TOPIC_LABELS.get(topic))}</li>`).join('')}</ul>`;
}

function caseCard(entry, href, headingLevel = 'h2') {
  const duration = durationLabel(entry.duration);
  return `<article class="case-card" data-topics="${escapeHtml(entry.topics.join(' '))}">
              <div class="case-card-thumb">
                <img src="https://i.ytimg.com/vi/${entry.youtubeId}/hqdefault.jpg" alt="" width="480" height="360" loading="lazy" decoding="async" />
                ${duration ? `<span class="case-card-duration">${duration}</span>` : ''}
              </div>
              <div class="case-card-body">
                <${headingLevel} class="case-card-title"><a href="${href}">${escapeHtml(entry.title)}</a></${headingLevel}>
                <p class="case-card-summary">${escapeHtml(entry.summary)}</p>
                ${topicTags(entry.topics)}
              </div>
            </article>`;
}

function renderGallery(cases) {
  const used = TOPICS.filter((topic) => cases.some((entry) => entry.topics.includes(topic.id)));
  const filters = cases.length > 0 && used.length > 1
    ? `<div class="case-filters" role="group" aria-label="Show cases about">
            <button type="button" class="case-filter" data-topic="" aria-pressed="true">All</button>
            ${used.map((topic) => `<button type="button" class="case-filter" data-topic="${topic.id}" aria-pressed="false">${escapeHtml(topic.label)}</button>`).join('\n            ')}
          </div>`
    : '';
  const grid = cases.length > 0
    ? `<div class="case-grid" id="caseGrid">
            ${cases.map((entry) => caseCard(entry, `./${entry.slug}/`)).join('\n            ')}
          </div>
          <p class="case-empty" id="caseFilterEmpty" hidden>No cases on this topic yet.</p>`
    : '<p class="case-empty">Case videos will appear here as they are published.</p>';

  const body = `      <main class="page-main">
        <section class="page-intro">
          <p class="section-eyebrow">Case videos</p>
          <h1 class="page-title">Real situations, explained with real figures.</h1>
          <p class="page-lede">
            Each video takes one person's situation and explains it with the figures on screen.
            Names are left out and the figures are rounded. These videos are education, not
            financial advice.
          </p>
          <div class="page-actions">
            <a class="button button-primary" href="../apply/">Apply with your situation</a>
          </div>
        </section>

        <section class="page-grid" aria-label="Case videos">
          ${filters}
          ${grid}
        </section>
      </main>`;

  return page({
    headHtml: head({
      title: 'Case videos | Planeir',
      description: 'Irish money questions from real people, explained in short education videos with the figures on screen. Names are left out and figures are rounded.',
      canonical: `${SITE}/cases/`,
      depth: 1
    }),
    depth: 1,
    body,
    scripts: filters ? '\n    <script type="module" src="../js/cases.js"></script>' : ''
  });
}

function situationHtml(entry) {
  return entry.situation.map((section) => `<div>
                <h3>${escapeHtml(section.heading)}</h3>
                <ul class="case-lines">
                  ${section.lines.map((line) => (typeof line === 'string'
    ? `<li>${escapeHtml(line)}</li>`
    : `<li>${escapeHtml(line.label)}<ul class="case-sublines">${line.lines.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul></li>`)).join('\n                  ')}
                </ul>
              </div>`).join('\n              ');
}

function renderCasePage(entry) {
  const canonical = `${SITE}/cases/${entry.slug}/`;
  const firstTopic = entry.topics[0];
  const applyHref = `../../apply/${firstTopic ? `?topic=${firstTopic}` : ''}`;
  const videoObject = {
    '@context': 'https://schema.org',
    '@type': 'VideoObject',
    name: entry.title,
    description: entry.summary,
    thumbnailUrl: [`https://i.ytimg.com/vi/${entry.youtubeId}/hqdefault.jpg`],
    uploadDate: entry.publishedDate,
    ...(entry.duration ? { duration: entry.duration } : {}),
    embedUrl: `https://www.youtube-nocookie.com/embed/${entry.youtubeId}`,
    url: canonical,
    inLanguage: 'en-IE',
    isFamilyFriendly: true,
    creator: { '@type': 'Person', name: 'Gerry Boylan', url: `${SITE}/` }
  };

  const body = `      <main class="page-main">
        <section class="page-intro">
          <p class="section-eyebrow">Case video · ${formatDate(entry.publishedDate)}</p>
          <h1 class="page-title">${escapeHtml(entry.title)}</h1>
          <p class="page-lede">${escapeHtml(entry.summary)}</p>
          ${topicTags(entry.topics)}
        </section>

        <div class="case-video">
          <iframe
            src="https://www.youtube-nocookie.com/embed/${entry.youtubeId}"
            title="${escapeHtml(entry.title)}"
            loading="lazy"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            referrerpolicy="strict-origin-when-cross-origin"
            allowfullscreen
          ></iframe>
        </div>

        <div class="case-layout">
          <section class="page-card" aria-labelledby="caseSituationTitle">
            <h2 id="caseSituationTitle">The situation</h2>
            <div class="case-situation">
              ${situationHtml(entry)}
            </div>
            <p class="case-meta">Figures are rounded and the name is left out.</p>
          </section>

          <div class="page-grid">
            <section class="page-card" aria-labelledby="caseQuestionTitle">
              <h2 id="caseQuestionTitle">The question</h2>
              <p class="case-question">${escapeHtml(entry.question)}</p>
            </section>
            ${entry.covers.length > 0 ? `<section class="page-card" aria-labelledby="caseCoversTitle">
              <h2 id="caseCoversTitle">What the video covers</h2>
              <ul>
                ${entry.covers.map((item) => `<li>${escapeHtml(item)}</li>`).join('\n                ')}
              </ul>
            </section>` : ''}
            <section class="page-card" aria-labelledby="caseApplyTitle">
              <h2 id="caseApplyTitle">Want your own situation explained?</h2>
              <p>Apply with your figures. Gerry reads every application and picks some to explain in a video.</p>
              <div class="page-actions">
                <a class="button button-primary" href="${applyHref}">Apply with your situation</a>
              </div>
            </section>
            <p class="case-meta">This video is financial education, not financial advice.</p>
          </div>
        </div>
      </main>`;

  return page({
    headHtml: head({
      title: `${entry.title} | Planeir case video`,
      description: entry.summary,
      canonical,
      depth: 2,
      extra: `
    <meta property="og:type" content="video.other" />
    <meta property="og:image" content="https://i.ytimg.com/vi/${entry.youtubeId}/hqdefault.jpg" />
    <meta name="twitter:card" content="summary_large_image" />
    <script type="application/ld+json">
${jsonForScript(videoObject)}
    </script>`
    }),
    depth: 2,
    body
  });
}

function renderLatestBlock(cases) {
  const latest = cases.slice(0, LATEST_COUNT);
  const inner = latest.length > 0
    ? `<div class="case-grid">
            ${latest.map((entry) => caseCard(entry, `./cases/${entry.slug}/`, 'h3')).join('\n            ')}
          </div>`
    : '<p class="case-empty">Case videos will appear here as they are published.</p>';
  return `${LATEST_START}
          ${inner}
          ${LATEST_END}`;
}

function renderSitemap(cases) {
  const urls = [
    ...STATIC_PAGES.map((pagePath) => `  <url>\n    <loc>${SITE}${pagePath}</loc>\n  </url>`),
    ...cases.map((entry) => `  <url>\n    <loc>${SITE}/cases/${entry.slug}/</loc>\n    <lastmod>${entry.publishedDate}</lastmod>\n  </url>`)
  ];
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join('\n')}
</urlset>
`;
}

function withLatestBlock(homeHtml, block) {
  const start = homeHtml.indexOf(LATEST_START);
  const end = homeHtml.indexOf(LATEST_END);
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`index.html must contain ${LATEST_START} and ${LATEST_END}.`);
  }
  return `${homeHtml.slice(0, start)}${block}${homeHtml.slice(end + LATEST_END.length)}`;
}

/* ---------- writing or checking ---------- */

async function readIfExists(file) {
  try {
    return await readFile(file, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw error;
  }
}

/** Case page folders this script made earlier, found by the marker it writes. */
async function generatedCaseSlugs() {
  let entries = [];
  try {
    entries = await readdir(CASES_DIR, { withFileTypes: true });
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
  const slugs = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const html = await readIfExists(path.join(CASES_DIR, entry.name, 'index.html'));
    if (html && html.includes(MARKER)) slugs.push(entry.name);
  }
  return slugs;
}

async function main() {
  const { published, drafts, problems } = await loadCases();
  if (problems.length > 0) {
    console.error('Case content has problems:');
    problems.forEach((problem) => console.error(`  - ${problem}`));
    process.exitCode = 1;
    return;
  }
  drafts.forEach((file) => console.log(`Skipped draft (no youtubeId yet): ${file}`));

  const outputs = new Map();
  outputs.set(path.join(CASES_DIR, 'index.html'), renderGallery(published));
  published.forEach((entry) => outputs.set(path.join(CASES_DIR, entry.slug, 'index.html'), renderCasePage(entry)));
  outputs.set(SITEMAP_FILE, renderSitemap(published));
  const home = await readFile(HOME_FILE, 'utf8');
  outputs.set(HOME_FILE, withLatestBlock(home, renderLatestBlock(published)));

  const publishedSlugs = new Set(published.map((entry) => entry.slug));
  const staleSlugs = (await generatedCaseSlugs()).filter((slug) => !publishedSlugs.has(slug));

  if (checkOnly) {
    const stale = [];
    for (const [file, content] of outputs) {
      if ((await readIfExists(file)) !== content) stale.push(path.relative(ROOT, file));
    }
    staleSlugs.forEach((slug) => stale.push(`cases/${slug}/ (no longer in content/cases)`));
    if (stale.length > 0) {
      console.error('Case pages are out of date. Run: npm run generate:cases');
      stale.forEach((file) => console.error(`  - ${file}`));
      process.exitCode = 1;
      return;
    }
    console.log(`Case pages are up to date (${published.length} published).`);
    return;
  }

  for (const [file, content] of outputs) {
    if ((await readIfExists(file)) === content) continue;
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, content, 'utf8');
    console.log(`Wrote ${path.relative(ROOT, file)}`);
  }
  for (const slug of staleSlugs) {
    await rm(path.join(CASES_DIR, slug), { recursive: true, force: true });
    console.log(`Removed cases/${slug}/`);
  }
  console.log(`Case pages generated (${published.length} published).`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
